WITH params AS (SELECT max(snapshot_date) as max_filtered_date, today() as sys_today FROM gold.rmv_l5_task_completion_v2 WHERE (snapshot_date = toDate('2024-10-31')) AND region = 'CNS' AND plant = 'DG3' AND factory = 'SMT' AND line = 'ST02' AND vx_type = 'V1'), calc_anchor AS (SELECT CASE WHEN max_filtered_date >= sys_today THEN sys_today ELSE max_filtered_date END as anchor_dt, sys_today FROM params), base AS (SELECT * FROM gold.rmv_l5_task_completion_v2 CROSS JOIN calc_anchor WHERE snapshot_date >= toStartOfMonth(anchor_dt) - INTERVAL 1 MONTH AND snapshot_date <= toLastDayOfMonth(anchor_dt) + INTERVAL 1 MONTH AND region = 'CNS' AND plant = 'DG3' AND factory = 'SMT' AND line = 'ST02' AND vx_type = 'V1') SELECT 'Month' as granularity, formatDateTime(anchor_dt, '%b.') as period_name, 1 as sort_order, vx_type, region, plant, factory, line, anchor_dt as filter_date, anchor_dt as snapshot_date_real, sum(total_task) as total_qty, sum(todo_count) as todo_qty, sum(doing_count) as doing_qty, sum(doing_count + done_count) as doing_done_qty, sum(done_count) as done_qty, argMax(acc_todo_doing, snapshot_date) as acc_qty, sum(total_task) as acc_total_qty FROM base CROSS JOIN calc_anchor WHERE snapshot_date >= toStartOfMonth(anchor_dt) AND snapshot_date <= anchor_dt GROUP BY vx_type, region, plant, factory, line, anchor_dt, period_name UNION ALL SELECT 'Week' as granularity, concat('W', toString(toWeek(snapshot_date, 1))) as period_name, CASE WHEN toWeek(snapshot_date, 1) = toWeek(anchor_dt, 1) THEN 2 WHEN toWeek(snapshot_date, 1) = toWeek(anchor_dt - INTERVAL 7 DAY, 1) THEN 3 ELSE 4 END as sort_order, vx_type, region, plant, factory, line, anchor_dt as filter_date, max(snapshot_date) as snapshot_date_real, sum(total_task) as total_qty, sum(todo_count) as todo_qty, sum(doing_count) as doing_qty, sum(doing_count + done_count) as doing_done_qty, sum(done_count) as done_qty, argMax(acc_todo_doing, snapshot_date) as acc_qty, sum(total_task) as acc_total_qty FROM base CROSS JOIN calc_anchor WHERE ((toWeek(snapshot_date, 1) = toWeek(anchor_dt, 1) AND snapshot_date <= anchor_dt) OR (toWeek(snapshot_date, 1) = toWeek(anchor_dt - INTERVAL 7 DAY, 1)) OR (toWeek(snapshot_date, 1) = toWeek(anchor_dt - INTERVAL 14 DAY, 1))) GROUP BY granularity, period_name, sort_order, vx_type, region, plant, factory, line, anchor_dt UNION ALL SELECT granularity, period_name, sort_order, vx_type, region, plant, factory, line, filter_date, snapshot_date_real, total_qty, todo_qty, doing_qty, doing_done_qty, done_qty, acc_qty, sum(total_qty) OVER (PARTITION BY vx_type, region, plant, factory, line ORDER BY snapshot_date_real ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) as acc_total_qty FROM (SELECT 'Day' as granularity, toString(snapshot_date) as period_name, 5 + dateDiff('day', snapshot_date, anchor_dt) as sort_order, vx_type, region, plant, factory, line, anchor_dt as filter_date, snapshot_date as snapshot_date_real, total_task as total_qty, todo_count as todo_qty, doing_count as doing_qty, (doing_count + done_count) as doing_done_qty, done_count as done_qty, acc_todo_doing as acc_qty FROM base CROSS JOIN calc_anchor WHERE snapshot_date BETWEEN (anchor_dt - INTERVAL 13 DAY) AND anchor_dt) AS daily_stream WHERE snapshot_date_real BETWEEN (filter_date - INTERVAL 6 DAY) AND filter_date UNION ALL SELECT 'FilterRef' as granularity, '' as period_name, 99 as sort_order, '' as vx_type, '' as region, '' as plant, '' as factory, '' as line, snapshot_date as filter_date, snapshot_date as snapshot_date_real, 0 as total_qty, 0 as todo_qty, 0 as doing_qty, 0 as doing_done_qty, 0 as done_qty, 0 as acc_qty, 0 as acc_total_qty FROM (SELECT DISTINCT snapshot_date FROM gold.rmv_l5_task_completion_v2);
